import{_ as i,l as o,o as e,c as s,v as t,p as l,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"两级与锦标赛预测","description":"","frontmatter":{"title":"两级与锦标赛预测","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tournament-predict.md","filePath":"cs/tournament-predict.md","lastUpdated":1789023840000}'),h={name:"cs/tournament-predict.md"};function E(P,a,m,_,T,A){const n=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="两级与锦标赛预测" tabindex="-1">两级与锦标赛预测 <a class="header-anchor" href="#两级与锦标赛预测" aria-label="Permalink to &quot;两级与锦标赛预测&quot;">​</a></h1><div class="epigraph"><p>有的分支跟自己的历史走，有的跟全局模式走；再用一位选择器记下「上次谁对」，比单一计数器更少误预测。</p><footer>—— 据 Yeh and Patt, Two-Level Adaptive Training Branch Prediction, MICRO 1991；McFarling, Combining Branch Predictors, WRL TN-36, 1993 整理</footer></div><p><a href="/cs/btb-ras">上一课</a>让 IF 拿到目标，方向仍可用一位饱和计数。<a href="/cs/control-hazard-predict">控制冒险与分支预测</a>已钉「猜 + 核对 + 冲刷」。本课不重讲 BTB。缺口是：一位计数把「这段循环将退出」记成与「循环体反复成功」同一条状态，相关分支互相污染。本课只交出两级自适应与锦标赛（竞赛）选择器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>循环末尾的 <code>bne</code> 连续多次成功，一位预测器在出口那一次必错。更糟的是：分支 B 的方向依赖于不久前分支 A 的结果（相关），局部一位看不见 A。缺口不是再加大 BTB，而是<strong>用历史寄存器索引一张模式表，每个模式一个计数器</strong>，并承认局部历史与全局历史各有擅长，用选择器在二者间挑。</p><p>Yeh–Patt 的两级结构把「历史」与「预测器」拆开。McFarling 的锦标赛再加一个元预测器，记下最近谁赢。</p><p><span class="marginnote">gshare 用全局历史与 PC 异或后再索引，减轻别名。本课把它当作两级全局的一种索引函数，不另立课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>局部两级：每个分支 PC 一份局部历史移位寄存器（LHR），用 LHR 索引该分支的模式历史表（PHT），PHT 项是两位饱和计数器。全局两级：全体共享 GHR，索引共享或按 PC 分体的 PHT。</p><p>锦标赛：局部、全局各出一个预测，选择器（同样是按 PC 索引的两位计数器）挑一个送给 IF。核对后：正确的一侧强化，错误的一侧减弱；选择器向赢家挪。</p>',10)),(e(),l(c,null,{default:r(()=>[p(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PC%5B%22%E5%88%86%E6%94%AF%20PC%22%5D%20--%3E%20LOC%5B%22%E5%B1%80%E9%83%A8%E5%8E%86%E5%8F%B2%20%E2%86%92%20PHT%22%5D%0A%20%20GHR%5B%22GHR%22%5D%20--%3E%20GLO%5B%22%E5%85%A8%E5%B1%80%E5%8E%86%E5%8F%B2%20%E2%86%92%20PHT%22%5D%0A%20%20LOC%20--%3E%20SEL%5B%22%E9%80%89%E6%8B%A9%E5%99%A8%22%5D%0A%20%20GLO%20--%3E%20SEL%0A%20%20SEL%20--%3E%20IF%5B%22IF%20%E9%87%87%E7%94%A8%E4%B8%80%E4%BE%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>更新在提交或核对后进行，与<a href="/cs/pipeline-exception">流水线异常</a>的冲刷兼容：误路径上的投机更新必须收回或等确认。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>误预测率进 CPI：频率 × 误预测率 × 损失拍数。两级降低中间那一项；损失拍数仍由流水线深度决定。别名：不同分支撞同一 PHT 项，表现为噪声，加大表或更好的散列（gshare）缓解。</p><p>选择器学的是「这类分支信谁」，不是再猜一次方向。循环分支往往信局部；不规则相关信全局。没有一侧永远赢，这是竞赛的动机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 TAGE、感知机预测器写进主干。也不把预测器做成用户可编程架构状态。延迟槽对照是后课：早期 RISC 用软件填槽，而不是把 PHT 做大。</p><p>后课默认：教学核可以仍用一位计数器；谈到「现代条件预测」，默认两级或锦标赛，BTB/RAS 仍管目标。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两级：历史寄存器索引 PHT，每个模式一个饱和计数器。</li><li>锦标赛用元预测器在局部与全局之间选择。</li><li>精确异常与冲刷纪律是下一课；本课只要求投机更新可收回。</li><li>出处：Yeh and Patt, <em>MICRO</em>, 1991；McFarling, WRL TN-36, 1993；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const f=i(h,[["render",E]]);export{B as __pageData,f as default};
